import {createPortal} from 'react-dom';
import React,{useState} from 'react';import{createRoot}from'react-dom/client';import IGFilterEditor from '../../src/components/IGFilterEditor.jsx';import PhotoFrame from '../../src/components/templates/shared/PhotoFrame.jsx';import{UIProvider}from'../../src/context/UIContext.jsx';import{api}from'../../src/api/client.js';import '../../src/styles/index.css';import '../../src/styles/atelier.css';
api.post=async()=>({data:{url:location.origin+'/tests/fixtures/photo-frame.png'}});api.patch=async(_,b)=>({data:{themeSettings:b}});
function App(){const[inv,setInv]=useState({id:'frame-qa',themeSettings:{igFilterImageUrl:location.origin+'/tests/fixtures/photo-frame.png'}});return <UIProvider><main className="atelier-app" style={{display:'grid',gridTemplateColumns:'480px 390px',gap:40,padding:32,background:'#faf8ee'}}><IGFilterEditor invitation={inv} onUpdated={setInv} onLivePreview={patch=>setInv({...inv,...patch})}/><div><h2>Bingkai Foto — data uji</h2>{createPortal(<button style={{position:"fixed",top:10,right:10,zIndex:22001}} onClick={async()=>{const blob=await(await fetch('/assets/landing-canvas/couple.webp')).blob(),data=new DataTransfer();data.items.add(new File([blob],'contoh.webp',{type:'image/webp'}));const input=[...document.querySelectorAll('input[type=file]')].at(-1);input.files=data.files;input.dispatchEvent(new Event('change',{bubbles:true}))}}>Gunakan foto contoh</button>,document.body)}<PhotoFrame frameUrl={inv.themeSettings.igFilterImageUrl}/></div></main></UIProvider>};createRoot(document.getElementById('root')).render(<App/>);
